function polySearchResults(){if(polySearch.error)return `<div class="panel-body"><div class="banner rose">${esc(polySearch.error)}</div><p class="small-text subtle">The connector is implemented, but access could not be verified from this connection. No simulated liquidity is substituted.</p></div>`;if(!polySearch.markets.length)return polySearch.ran?`<div class="panel-body"><p class="small-text subtle">No outcomes returned for this search. Try a matchup or event name.</p></div>`:'';return `<div class="search-results">${polySearch.markets.map((m,i)=>`<div class="search-result"><div><h3>${esc(m.question)}</h3><p>${esc(m.outcome)} · ${m.closed?'Closed':'Listed active'} · Ends ${esc(day(m.end_date))}</p></div>${btn('Watch +','watch-search','small',`data-index="${i}"`)}</div>`).join('')}</div>`;}
function polyBook(w,b){
  const title=`<div class="panel-header" style="padding-left:0;padding-right:0"><div><h3>${esc(w.label)}</h3><p class="code">${esc(w.token_id.slice(0,18))}…</p></div>${btn('Remove','remove-poly','small ghost',`data-id="${esc(w.token_id)}"`)}</div>`;
  if(!b)return title+'<p class="form-note">Awaiting first snapshot. Use Refresh watchlist.</p>';
  const error=b.error?`<div class="banner rose">${esc(b.error)}${b.captured_at?` Last successful capture: ${esc(time(b.captured_at))}.`:''}</div>`:'';
  if(!b.bids)return title+error;
  const mx=Math.max(...b.bids.slice(0,8).map(x=>x.size),...b.asks.slice(0,8).map(x=>x.size),1);
  return title+error+`<div class="stats" style="margin:16px 0;grid-template-columns:repeat(4,1fr)">${stat('BID / ASK',`${fmt(b.best_bid,3)} / ${fmt(b.best_ask,3)}`,'Outcome share prices')}${stat('SPREAD',`${b.spread==null?'—':fmt(b.spread*100,1)+'¢'}`,'Best ask minus best bid')}${stat('ASK DEPTH · 2¢',money(b.ask_depth_dollars_2c),'Within 2 cents of best ask')}${stat('DEPTH IMBALANCE',signed(b.imbalance_2c,2),'Bid vs ask share depth')}</div><div class="wide-columns"><div class="book-grid"><div><h3><span>BIDS</span><span>SHARES</span></h3>${b.bids.slice(0,8).map(x=>`<div class="book-level" style="--width:${x.size/mx*100}%"><span>${fmt(x.price,3)}</span><span>${fmt(x.size,0)}</span></div>`).join('')||'<span class="subtle">No bids</span>'}</div><div class="asks"><h3><span>ASKS</span><span>SHARES</span></h3>${b.asks.slice(0,8).map(x=>`<div class="book-level" style="--width:${x.size/mx*100}%"><span>${fmt(x.price,3)}</span><span>${fmt(x.size,0)}</span></div>`).join('')||'<span class="subtle">No asks</span>'}</div></div><div><h3>A hypothetical $100 buy</h3><p class="small-text subtle">${fmt(b.hypothetical_buy?.shares)} shares at an average ${fmt(b.hypothetical_buy?.average_price,3)}. ${b.hypothetical_buy?.fully_filled?'Displayed depth covers the budget.':'Displayed depth does not cover the budget.'} Fees excluded; this is not an order.</p><p class="book-time" style="margin-top:12px">Captured ${esc(time(b.captured_at))}</p><p class="footer-note">${esc(b.trade_sample_note||b.wallet_error||'No wallet sample captured.')}</p></div></div>${b.wallets?.length?`<div class="table-wrap section-space"><table><thead><tr><th>Observed fill participant</th><th class="numeric">Sample rows</th><th class="numeric">Sample notional</th><th></th></tr></thead><tbody>${b.wallets.slice(0,6).map(x=>`<tr><td class="wallet-address">${esc(x.wallet.slice(0,10))}…${esc(x.wallet.slice(-6))}</td><td class="numeric">${x.trades}</td><td class="numeric">${money(x.notional)}</td><td>${btn('Track','wallet-from-book','small',`data-address="${esc(x.wallet)}"`)}</td></tr>`).join('')}</tbody></table></div>`:''}`;
}
function walletCard(w,d){return `<div style="padding:12px 0"><div style="display:flex;justify-content:space-between"><div><h3>${esc(w.label||'Public wallet')}</h3><p class="wallet-address">${esc(w.address)}</p></div>${btn('Remove','remove-wallet','small ghost',`data-address="${esc(w.address)}"`)}</div>${d?.error?`<div class="banner rose" style="margin-top:14px">${esc(d.error)}</div>`:''}${d?.positions?`<div class="status-row"><span>Captured open-position value</span><b>${money(d.sample_position_value)}</b></div><div class="status-row"><span>Positions / activity rows</span><b>${d.positions.length} / ${d.activity.length}</b></div><p class="footer-note">${esc(d.scope)} ${d.positions_pagination?.truncated?'Position sample truncated at 600 rows.':''} ${d.activity_pagination?.truncated?'Activity sample truncated at 600 rows.':''}</p><div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>Market</th><th>Outcome</th><th class="numeric">Size</th><th class="numeric">Value</th></tr></thead><tbody>${d.positions.slice(0,5).map(p=>`<tr><td class="audit-cell">${esc(p.title)}</td><td>${esc(p.outcome)}</td><td class="numeric">${fmt(p.current_size)}</td><td class="numeric">${money(p.current_value)}</td></tr>`).join('')}</tbody></table></div><p class="book-time" style="margin-top:12px">${esc(time(d.captured_at))}</p>`:'<p class="form-note">Awaiting first snapshot. Use Refresh watchlist.</p>'}</div>`;}

