function mlbPage(){
  const m=S.mlb,b=m.board,games=b.games||[],ready=games.filter(g=>g.display_status==='READY_RESEARCH');
  const quotes=(m.quotes||[]).slice().sort((a,b)=>b.captured_at.localeCompare(a.captured_at));
  const latest=new Map();for(const q of quotes){const key=[q.game_id,q.market_type,q.player_id,q.side,q.line,q.book].join('|');if(!latest.has(key))latest.set(key,q);}
  const rows=[...latest.values()].sort((a,b)=>b.ev-a.ev);
  const d=b.date||new Date().toISOString().slice(0,10);
  return head('OMEGA V2 · MLB POSTSEASON','October changes the opportunity.','Frozen playoff workload and moneyline candidates, with every result tied to a saved forecast.',`<a class="button" href="/api/mlb/frozen">Frozen model ↓</a>`)+
    `<div class="banner amber"><strong>Betting edge is not verified.</strong> The strikeout candidate improved historical prediction error. Moneyline challengers did not improve accuracy. Prices and prospective results must establish profitability before promotion.</div>`+
    (m.last_failure?`<div class="banner rose">Latest collection failed ${esc(time(m.last_failure.at))}: ${esc(m.last_failure.error)}. The previous board retains its capture time.</div>`:'')+
    (!m.node_available?`<div class="banner rose">Install Node 18 or newer to build MLB forecasts. The historical backtest is available below.</div>`:'')+
    `<div class="stats">${stat('PLAYOFF GAMES',games.length,b.date?esc(b.date):'Refresh an official game date',true)}${stat('RESEARCH FORECASTS',ready.length,'Both lineups and starters required')}${stat('PLAYOFF OUTS FACTOR',fmt(m.frozen.usage.factor,4),`${m.frozen.usage.training_pitcher_seasons} matched pitcher-seasons`)}${stat('VERIFIED BETTING EDGE','Pending','No model has passed the market gates')}</div>`+
    panel('Official playoff board','Pregame collection uses MLB, Baseball Savant and FanGraphs. Every captured source and forecast is retained.',`<div class="panel-body"><form id="mlb-refresh-form" class="inline-controls"><label class="small-text">Game date <input name="date" type="date" value="${esc(d)}" required></label><button class="button primary" type="submit">Refresh playoff inputs</button><span class="small-text subtle">Captured ${esc(time(b.captured_at))}</span></form></div>`+
      (games.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Game / first pitch</th><th>Status</th><th>Home win · baseline</th><th>Home win · candidate</th><th>Starter K · V2 (baseline)</th><th>DELTA xK · PA / beta</th><th>Input / forecast</th></tr></thead><tbody>${games.map(g=>`<tr><td><strong>${esc(g.away)} @ ${esc(g.home)}</strong><small>${esc(time(g.start_at))}</small></td><td>${tag(g.display_status||g.status,g.display_status==='READY_RESEARCH'?'amber':'plain')}</td><td>${pct(g.forecast?.moneyline.baseline_home_probability)}</td><td>${pct(g.forecast?.moneyline.calibrated_home_probability)}</td><td>${g.forecast?g.forecast.starters.map(s=>`${esc(s.player)} · ${fmt(s.expected_k,2)} <span class="subtle">(${fmt(s.baseline_k,2)})</span>`).join('<br>'):'—'}</td><td>${g.forecast?.delta?g.forecast.delta.map(d=>`${esc(d.player)} · ${fmt(d.pa.expected_k,2)} / ${fmt(d.beta_binomial.expected_k,2)}`).join('<br>'):'Refresh for DELTA'}</td><td class="wrap">${g.snapshot_id?`<a href="/api/snapshot?id=${encodeURIComponent(g.snapshot_id)}">Saved forecast ↓</a><small>${esc(time(g.captured_at))}</small>`:esc(g.reason)}</td></tr>`).join('')}</tbody></table></div>`:empty('Load the next playoff slate.','Choose a game date and refresh. Games with unpublished lineups stay blocked; finished games are never presented as pregame opportunities.')))+
    panel('Compare your available prices','Candidate expected return per unit at your price. Positive expected return is a model estimate; it does not establish an edge.',
      rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Game / selection</th><th>Book / capture</th><th>Odds</th><th>Fair odds</th><th>V2 EV</th><th>DELTA PA EV</th><th>Baseline EV</th><th>Status</th></tr></thead><tbody>${rows.slice(0,120).map(q=>{const g=games.find(g=>g.game_id===q.game_id),age=(Date.now()-Date.parse(q.captured_at))/60000,active=g?.display_status==='READY_RESEARCH'&&Date.now()<Date.parse(g.start_at)&&age<=20&&(Date.now()-Date.parse(g.captured_at))/60000<=20;return `<tr><td>${esc(q.game_id)} · ${esc(q.side)} ${q.market_type==='K'?esc(q.player_id)+' · '+fmt(q.line,1):''}</td><td>${esc(q.book)}<small>${esc(time(q.captured_at))}</small></td><td>${signed(q.odds,0)}</td><td>${signed(q.fair_odds,0)}</td><td>${pct(q.ev,2)}</td><td>${pct(q.delta_ev,2)}</td><td>${pct(q.baseline_ev,2)}</td><td>${tag(active?'Research only':'Stale / started','amber')}</td></tr>`;}).join('')}</tbody></table></div>`:empty('No MLB prices captured.','Download the template and import the exact game, pitcher, line, side, book and capture time. Imported prices remain unverified.'),btn('Import MLB quote CSV','mlb-import')+'<a class="button" href="/api/mlb/quote-template.csv">CSV template ↓</a>')+
    panel('Prospective evidence journal','Forecasts are saved before first pitch. Grading checks official finals and the actual starting pitcher identity.',`<div class="panel-body"><p class="small-text">${fmt(m.prospective.graded_quotes||0,0)} quotes graded. Imported prices are unverified; repeated quotes are not independent wagers. ${esc(m.prospective.note||'The 2026 model stays frozen while new results accumulate.')}</p><div class="insight-callout">Workload estimates from regular-season history receive the playoff adjustment. A current-game workload anchor or explicit manager plan keeps its existing leash.</div></div>`,btn('Grade official finals','mlb-grade')+btn('Open historical backtest','mlb-backtest'));
}

function mlbBacktest(){
  const r=S.mlb.report,k=r.strikeouts,ml=r.moneyline_calibrated,ci=k.challenger_minus_baseline.mae.series_ci95;
  const interval=v=>v?`[${signed(v[0],4)}, ${signed(v[1],4)}]`:'—';
  return head('OMEGA V2 · CHRONOLOGICAL DEVELOPMENT TEST','Prediction improved. Profitability is unverified.','Each test postseason uses parameters learned only from earlier postseasons. Previously inspected years remain development evidence.','<a class="button" href="/api/mlb/report">Full backtest JSON ↓</a>')+
    `<div class="banner amber">EDGE NOT VERIFIED · No accepted historical entry price pairs. ROI, closing-line value and performance against the market are unmeasured. Moneyline changes have not earned promotion.</div>`+
    `<div class="stats">${stat('OFFICIAL PLAYOFF GAMES',r.coverage.official_games,'2015–2025',true)}${stat('PROJECTED / BLOCKED',`${r.coverage.projected_games} / ${r.coverage.blocked_games}`,'Missing inputs remain excluded and listed')}${stat('PAIRED STARTER K TESTS',k.paired_n,'2015 warm-up; relief proxies excluded')}${stat('K MAE IMPROVEMENT',pct((k.baseline.mae-k.challenger.mae)/k.baseline.mae,1),'Historical prediction error')}</div>`+
    panel('Starter strikeouts','Playoff outs → batters faced → strikeouts. No current strikeout line is used to set the expected mean.',`<div class="table-wrap"><table class="data-table"><thead><tr><th>Model</th><th>Starts</th><th>MAE ↓</th><th>RMSE ↓</th><th>Bias</th><th>Distribution log loss ↓</th><th>Ranked probability score ↓</th></tr></thead><tbody>${[['Recovered baseline',k.baseline],['V2 playoff candidate',k.challenger]].map(([label,a])=>`<tr><td>${label}</td><td>${a.n}</td><td>${fmt(a.mae,4)}</td><td>${fmt(a.rmse,4)}</td><td>${signed(a.bias,4)}</td><td>${fmt(a.log_loss,4)}</td><td>${fmt(a.ranked_probability_score,4)}</td></tr>`).join('')}</tbody></table></div><div class="panel-body"><p class="small-text">Candidate minus baseline MAE: ${signed(k.challenger_minus_baseline.mae.delta,4)}. 95% series interval ${interval(ci)}; season interval ${interval(k.challenger_minus_baseline.mae.season_ci95)}. Intervals resample complete series or seasons, using 2,000 fixed-seed draws.</p></div>`)+
    panel('Moneyline candidates','Lower Brier and log loss are better. Exposure and calibration challengers are both retained.',`<div class="table-wrap"><table class="data-table"><thead><tr><th>Comparison</th><th>Paired games</th><th>Baseline Brier</th><th>Candidate Brier</th><th>Baseline log loss</th><th>Candidate log loss</th><th>Brier change · series 95%</th></tr></thead><tbody>${[['Short-start exposure',r.moneyline_exposure],['Exposure + prior-year calibration',ml]].map(([label,a])=>`<tr><td>${label}</td><td>${a.paired_n}</td><td>${fmt(a.baseline.brier,5)}</td><td>${fmt(a.challenger.brier,5)}</td><td>${fmt(a.baseline.log_loss,5)}</td><td>${fmt(a.challenger.log_loss,5)}</td><td>${signed(a.challenger_minus_baseline.brier.delta,5)} ${interval(a.challenger_minus_baseline.brier.series_ci95)}</td></tr>`).join('')}</tbody></table></div>`)+
    panel('Season checks','2020 and the expanded Wild Card era are also reported separately in the full export.',`<div class="table-wrap"><table class="data-table"><thead><tr><th>Season</th><th>Training pitcher-seasons</th><th>Outs factor</th><th>K pairs</th><th>Baseline K MAE</th><th>V2 K MAE</th><th>ML pairs</th><th>Baseline Brier</th><th>V2 Brier</th></tr></thead><tbody>${Object.entries(r.per_season).map(([year,a])=>`<tr><td>${year}</td><td>${a.usage_training.training_pitcher_seasons}</td><td>${fmt(a.usage_training.factor,4)}</td><td>${a.strikeouts.baseline.n}</td><td>${fmt(a.strikeouts.baseline.mae,3)}</td><td>${fmt(a.strikeouts.challenger.mae,3)}</td><td>${a.moneyline.baseline.n}</td><td>${fmt(a.moneyline.baseline.brier,4)}</td><td>${fmt(a.moneyline.challenger.brier,4)}</td></tr>`).join('')}</tbody></table></div>`)+
    panel('Verification gates','The model remains research until all market and confirmation requirements pass.',`<div class="panel-body"><div class="status-list">${Object.entries(r.verification_gates).map(([label,passed])=>`<div class="status-row"><span>${esc(label.replaceAll('_',' '))}</span>${tag(passed?'Passed':'Unverified',passed?'green':'amber')}</div>`).join('')}</div>${r.limitations.map(x=>`<p class="small-text subtle">${esc(x)}</p>`).join('')}<details><summary>${r.coverage.blocked_games} blocked games</summary>${r.coverage.blocked.map(b=>`<p class="small-text">${esc(b.game_date)} · ${esc(b.game_id)} · ${esc(b.error)}</p>`).join('')}</details></div>`);
}

function deltaEntries(){
  const entries=(S.mlb.board.games||[]).flatMap(g=>(g.forecast?.delta||[]).map(d=>({d,g,key:g.game_id+':'+d.player_id})));
  entries.push({key:'REPLAY',d:S.mlb.delta.replay_example,g:null});
  return entries;
}
function deltaSelected(){
  const entries=deltaEntries();
  return entries.find(e=>e.key===deltaKey)||entries.find(e=>e.g?.display_status==='READY_RESEARCH')||entries.at(-1);
}
function deltaProbs(pmf,line){return {over:pmf.reduce((s,p,k)=>s+(k>line?p:0),0),under:pmf.reduce((s,p,k)=>s+(k<line?p:0),0),push:pmf.reduce((s,p,k)=>s+(k===line?p:0),0)};}
function deltaPage(){
  const state=S.mlb.delta,{d,g,key}=deltaSelected(),pa=d.pa,beta=d.beta_binomial,probs=deltaProbs(pa.pmf,deltaLine),bprobs=deltaProbs(beta.pmf,deltaLine);
  const priceValid=Number.isFinite(deltaOdds)&&Math.abs(deltaOdds)>=100&&Math.abs(deltaOdds)<=100000;
  const profit=priceValid?(deltaOdds>0?deltaOdds/100:100/Math.abs(deltaOdds)):null;
  const old=g&&Date.now()>=Date.parse(g.start_at),last=state.last_simulation;
  return head('DELTA 0.1 · MLB POSTSEASON','Build the count from the matchups.','A probability for each hitter, a distribution for the workload, and a saved record for every forecast.',`<a class="button" href="/api/delta/frozen">DELTA parameters ↓</a>`)+
    `<div class="banner amber"><strong>Research model · promotion not earned.</strong> On 775 historical starts, DELTA PA MAE is ${fmt(state.report.models.delta_pa.mae,3)} versus V2 ${fmt(state.report.models.v2.mae,3)}. Advanced pitch and manager inputs still need historical validation. ${btn('Inspect evidence','delta-backtest','small')}</div>`+
    panel('Choose a pitcher','Current saved DELTA forecasts appear after refreshing the playoff board.',`<div class="panel-body"><select id="delta-selection" class="input" aria-label="DELTA pitcher">${deltaEntries().map(e=>option(e.key,e.g?`${e.g.away} @ ${e.g.home} · ${e.d.player} · ${e.g.display_status||e.g.status}`:`Historical replay · ${e.d.game_date} · ${e.d.player}`,key)).join('')}</select><p class="small-text">${g?`${esc(g.away)} @ ${esc(g.home)} · saved ${esc(time(g.captured_at))}${old?' · game started; saved research only':''}`:`Historical replay example from ${esc(d.game_date)} · actual ${fmt(d.actual_k,0)} K. This is reconstructed historical evidence.`}</p></div>`,btn('Open playoff board','delta-board'))+
    `<div class="stats">${stat('DELTA PA xK',fmt(pa.expected_k,2),esc(d.player),true)}${stat('EXPECTED BATTERS',fmt(d.expected_bf,2),`${pct(d.probability_bf_over_18)} chance of more than 18 BF`)}${stat('K 10TH / MEDIAN / 90TH',`${pa.p10} / ${pa.p50} / ${pa.p90}`,'Outcome percentiles, not parameter confidence')}${stat('BETA-BINOMIAL xK',fmt(beta.expected_k,2),`Concentration ${fmt(d.beta_concentration,0)} · research comparison`)}</div>`+
    `<div class="wide-columns">${panel('Strikeout distribution','PA keeps hitter-specific probabilities. Beta-binomial adds shared efficiency variation.',`<div class="panel-body"><div class="delta-legend"><span>● PA</span><span>● Beta-binomial</span></div><div class="delta-bars" role="img" aria-label="Exact strikeout probabilities">${pa.pmf.slice(0,21).map((p,k)=>`<div class="delta-bar-row"><span>${k} K</span><div><i style="width:${Math.min(100,p*400)}%"></i><b style="width:${Math.min(100,(beta.pmf[k]||0)*400)}%"></b></div><small>${pct(p,1)}</small></div>`).join('')}</div><p class="small-text subtle">PA variance ${fmt(pa.variance,3)} · beta variance ${fmt(beta.variance,3)}. Probability above 20 K: ${pct(pa.pmf.slice(21).reduce((a,b)=>a+b,0),3)}.</p></div>`)}${panel('Line & price calculator','Illustrative price only; this calculator does not record a quote or bet.',`<div class="panel-body"><div class="field-row"><label class="field">K line<input class="input" id="delta-line" type="number" min="0" max="100" step=".5" value="${deltaLine}"></label><label class="field">American odds<input class="input" id="delta-odds" type="number" value="${Number.isFinite(deltaOdds)?deltaOdds:''}"></label></div><table class="data-table"><thead><tr><th>Distribution</th><th>Over</th><th>Under</th><th>Push</th></tr></thead><tbody>${[['PA',probs],['Beta-binomial',bprobs]].map(([name,p])=>`<tr><td>${name}</td><td>${pct(p.over)}</td><td>${pct(p.under)}</td><td>${pct(p.push)}</td></tr>`).join('')}</tbody></table><p class="small-text">PA modeled EV at this illustrative price: over ${priceValid?pct(probs.over*profit-probs.under,2):'—'}; under ${priceValid?pct(probs.under*profit-probs.over,2):'—'}. Integer pushes return the stake.</p></div>`)}</div>`+
    panel('Exact batting-order matchups','Shrunk pitcher and batter rates enter log-5. Splits and pitch models are used only when supplied.',`<div class="table-wrap"><table class="data-table"><thead><tr><th>Order</th><th>Hitter / MLBAM ID</th><th>K per PA</th><th>Pitcher split</th><th>Batter split</th><th>Method</th></tr></thead><tbody>${d.hitters.map(h=>`<tr><td>${h.order}</td><td>${esc(h.player)}<small>${esc(h.player_id)}</small></td><td>${pct(h.k_probability)}</td><td>${h.pitcher_split_used?'Used':'Missing'}</td><td>${h.batter_split_used?'Used':'Missing'}</td><td>${esc(h.mode.replaceAll('_',' '))}</td></tr>`).join('')}</tbody></table></div>`)+
    (d.research?panel('Unfitted matchup research','These sourced estimates are saved alongside the forecast; they do not change DELTA probabilities.',`<div class="table-wrap"><table class="data-table"><thead><tr><th>Order</th><th>Hitter ID</th><th>Platoon estimate</th><th>Hitter split</th><th>Arsenal whiff / swing</th></tr></thead><tbody>${d.research.lineup.map(r=>`<tr><td>${r.order}</td><td>${esc(r.player_id)}</td><td>${r.matchup_log5_unfitted==null?'—':pct(r.matchup_log5_unfitted)}</td><td>${esc(r.batter_split?.status||r.status)}</td><td>${r.arsenal_whiff?pct(r.arsenal_whiff.weighted_whiff_per_swing):'—'}</td></tr>`).join('')}</tbody></table></div><div class="panel-body"><p class="small-text">Prior source: ${esc(d.research.source)} · cutoff ${esc(d.research.training_end_at)}. FF velocity trend: ${d.research.four_seam_trend?.change_mph==null?esc(d.research.four_seam_trend?.status||'Missing'):`${signed(d.research.four_seam_trend.change_mph,2)} mph (measured only)`}. No Stuff+ scaling or validated K effect.</p></div>`):'')+
    panel('Advanced input coverage','Stuff+/PitchingBot, command, CSW, whiff/chase, arsenal matchups, umpire/weather, bullpen, series and familiarity have explicit input fields.',`<div class="panel-body"><div class="status-list">${Object.entries(d.advanced_layers).map(([name,status])=>`<div class="status-row"><span>${esc(name.replaceAll('_',' '))}</span>${tag(status.replaceAll('_',' '),'amber')}</div>`).join('')}</div><p class="small-text">${state.profile_count} imported pitcher-game profiles. Missing metrics have no automatic boost. Imported coefficients require a source and a training cutoff; their authenticity and forecast value remain unverified.</p><p class="small-text">Manager hook scenarios can use pitch count, third trip through the order, runners, runs, leverage, bullpen availability and elimination status. They replace the independent workload draw and use simplified base advancement.</p>${d.feature_profile_snapshot_id?`<a href="/api/snapshot?id=${encodeURIComponent(d.feature_profile_snapshot_id)}">Saved feature source ↓</a>`:''}<details><summary>Model assumptions</summary>${d.notes.map(n=>`<p class="small-text">${esc(n)}</p>`).join('')}</details></div>`,btn('Import advanced JSON','delta-import')+'<a class="button" href="/api/delta/input-template.json">Input template ↓</a>')+
    panel('Public pitch-data preparation','Optional pybaseball, Baseball Savant CSV and baseballr exports.',`<div class="panel-body"><p class="small-text">Fetch the confirmed starter and nine hitters in regular-season batches, or use an existing Savant CSV. The converter verifies batch hashes, exact MLBAM IDs and a pregame date cutoff, then makes a DELTA profile for the import control above. It keeps normalized pitch and play-by-play rows for later model fitting.</p><p class="small-text">With independently sourced league and player priors, an optional research matrix estimates small or absent hand splits and pitch-type whiff matchups. It labels estimates separately from measured data. A dynamic PA hook matrix and ridge-logit trainers are research tools; none have fitted coefficients or historical score improvements in this release.</p></div>`,'<a class="button" href="/api/delta/data-sources.md">Data-source guide ↓</a>')+
    panel('DELTA simulation','Repeat the saved inputs with a reproducible seed. Count transitions run when all relevant probabilities are supplied.',`<div class="panel-body">${g?.snapshot_id?`<form id="delta-sim-form" class="inline-controls"><input type="hidden" name="snapshot_id" value="${esc(g.snapshot_id)}"><input type="hidden" name="player_id" value="${esc(d.player_id)}"><label>Draws <input class="input" name="draws" type="number" min="1000" max="50000" value="10000" required></label><label>Seed <input class="input" name="seed" type="number" min="0" max="4294967295" value="61026" required></label><button class="button primary" type="submit">Run simulation</button></form>`:`<p class="small-text">Refresh a future playoff game to save DELTA inputs and enable simulations. The replay example is a historical comparison.</p>`}${last?`<div class="insight-callout">${esc(last.player)} · ${fmt(last.draws,0)} draws · ${esc(last.mode)}<br>Monte Carlo xK ${fmt(last.distribution.expected_k,3)} · sampling SE ${fmt(last.expected_k_mc_se,4)} · expected BF ${fmt(last.expected_bf,2)}<br><a href="/api/snapshot?id=${encodeURIComponent(last.snapshot_id)}">Saved simulation ↓</a></div>`:''}</div>`)+
    panel('Prospective DELTA grading','Latest locally saved forecast before first pitch, once per game and pitcher. Official starting-pitcher identity must match.',`<div class="panel-body"><p class="small-text">Freeze ${esc(state.prospective.frozen_at)} · only locally received forecasts after this time and before first pitch can join the new prospective cohort. Earlier 2026 games remain development or retrospective records.</p><p class="small-text">${state.grading.graded_starts||0} starts graded · ${state.grading.pending?.length||0} awaiting a final or identity match. The general grader may include older saved forecasts; the separate prospective audit applies the freeze cutoff. No automatic refit or promotion.</p></div>`,btn('Grade official DELTA counts','delta-grade'));
}
function deltaBacktest(){
  const r=S.mlb.delta.report,c=S.mlb.delta.counterfactual,labels={baseline:'Recovered baseline',v2:'V2 playoff candidate',delta_pa:'DELTA · PA',delta_beta:'DELTA · beta-binomial',boost_1_04:'DELTA · 1.04 K multiplier',bf_cap_19:'DELTA · 19 BF cap',boost_and_cap:'DELTA · both adjustments'};
  const table=values=>`<div class="table-wrap"><table class="data-table"><thead><tr><th>Model</th><th>Starts</th><th>MAE ↓</th><th>RMSE ↓</th><th>Bias</th><th>Log loss ↓</th><th>RPS ↓</th></tr></thead><tbody>${Object.entries(values).map(([name,a])=>`<tr><td>${labels[name]}</td><td>${a.n}</td><td>${fmt(a.mae,4)}</td><td>${fmt(a.rmse,4)}</td><td>${signed(a.bias,4)}</td><td>${fmt(a.log_loss,4)}</td><td>${fmt(a.ranked_probability_score,4)}</td></tr>`).join('')}</tbody></table></div>`;
  return head('DELTA · CHRONOLOGICAL DEVELOPMENT EVIDENCE','The challenger must earn its place.','The same 775 starts, all variants reported, and parameters fitted only on earlier postseasons.','<a class="button" href="/api/delta/report">Complete DELTA report ↓</a>')+
    `<div class="banner amber"><strong>DELTA 0.1 does not beat V2 in this replay.</strong> Its PA and beta-binomial variants have higher mean error and distribution scores. Pitch-level and dynamic manager layers were not historically tested. Betting edge is unmeasured.</div>`+
    panel('Paired starter strikeouts','2016–2025 tests; 2015 warm-up. Independent future confirmation is still required.',table(r.models))+
    panel('Proposed fixed postseason adjustments','Same 775 previously inspected starts; experimental comparison, no model promotion.',table({v2:c.reference_v2,delta_pa:c.models.delta_unchanged,boost_1_04:c.models.boost_1_04,bf_cap_19:c.models.bf_cap_19,boost_and_cap:c.models.boost_and_cap})+`<div class="panel-body"><p class="small-text">${fmt(c.actual_bf.over_19,0)} of ${fmt(c.n,0)} actual starters faced more than 19 batters. The 4% multiplier worsened MAE and distribution scores; the cap slightly reduced MAE but worsened log loss and RPS. The combined variant still trailed V2.</p></div>`,'<a class="button" href="/api/delta/escalator-report">Experiment audit ↓</a>')+
    panel('Recent playoff format','2022 onward; a reported sensitivity, not a selected test sample.',table(r.sensitivities['2022_onward']))+
    panel('2020 excluded','Reported separately to expose the unusual season and playoff structure.',table(r.sensitivities.without_2020))+
    panel('Season detail','Workload shape, skill intercept and beta concentration use earlier seasons only.',`<div class="table-wrap"><table class="data-table"><thead><tr><th>Season</th><th>Starts</th><th>V2 MAE</th><th>DELTA PA MAE</th><th>V2 log loss</th><th>DELTA PA log loss</th><th>DELTA beta log loss</th></tr></thead><tbody>${Object.entries(r.per_season).map(([year,a])=>`<tr><td>${year}</td><td>${a.v2.n}</td><td>${fmt(a.v2.mae,3)}</td><td>${fmt(a.delta_pa.mae,3)}</td><td>${fmt(a.v2.log_loss,3)}</td><td>${fmt(a.delta_pa.log_loss,3)}</td><td>${fmt(a.delta_beta.log_loss,3)}</td></tr>`).join('')}</tbody></table></div>`)+
    panel('Historical market benchmark','A separate audit joins supplied opening and closing K lines to exact saved PMFs. Closing prices are a benchmark; they do not set the forecast.',(()=>{const a=S.mlb.delta.market_audit;if(!a)return `<div class="panel-body"><p class="small-text">No matched historical market file has been audited. Download the CSV contract, then run <span class="code">tools/evaluate_delta_market.py</span> locally.</p></div>`;return `<div class="panel-body"><div class="status-list"><div class="status-row"><span>Matched rows</span><b>${fmt(a.matched_rows,0)}</b></div><div class="status-row"><span>Model / market Brier</span><b>${fmt(a.model_vs_market.model_brier,4)} / ${fmt(a.model_vs_market.market_brier,4)}</b></div><div class="status-row"><span>Opening bets · realized ROI</span><b>${fmt(a.bets,0)} · ${a.roi.mean_realized_roi_per_unit==null?'—':pct(a.roi.mean_realized_roi_per_unit,2)}</b></div><div class="status-row"><span>Same-line CLV</span><b>${a.clv.mean_no_vig_probability_move==null?'—':signed(a.clv.mean_no_vig_probability_move,4)}</b></div></div><p class="small-text">${esc(a.status)} · no automatic promotion.</p></div>`})(),'<a class="button" href="/api/delta/market-template.csv">Market CSV template ↓</a>'+(S.mlb.delta.market_audit?'<a class="button" href="/api/delta/market-audit">Audit JSON ↓</a>':''))+ 
    panel('What remains unverified','These gaps define the next data and fitting work.',`<div class="panel-body">${r.limitations.map(s=>`<p class="small-text">${esc(s)}</p>`).join('')}<p class="small-text">ROI: unmeasured · CLV: unmeasured · advanced feature replay: not run. The new hazard and platoon/arsenal matrix tools have no frozen historical improvement claim.</p></div>`,btn('Return to DELTA','delta-model'));
}

function render(){
  if(!S)return;
  document.querySelectorAll('[data-nav]').forEach(n=>n.classList.toggle('active',n.dataset.nav===tab));
  $('#breadcrumb-page').textContent=titles[tab];
  document.title=`${titles[tab]} · OMEGA Next`;
  $('#screen').innerHTML=({collector:collectorPage,delta:deltaPage,deltatest:deltaBacktest,mlb:mlbPage,mlbtest:mlbBacktest,forecasts,lab:labPage,review:reviewPage,markets:marketsPage,bets:betsPage,poly:polyPage,validation:validationPage,system:systemPage}[tab]||forecasts)();
  if(S.jobs?.some(j=>j.status==='RUNNING'))$('#screen').insertAdjacentHTML('afterbegin',`<div class="banner"><span class="spinner"></span> Running: ${S.jobs.filter(j=>j.status==='RUNNING').map(j=>esc(j.kind)).join(', ')}. You can navigate while it completes.</div>`);
  if(tab==='markets'&&S.odds_last_failure)$('#screen').insertAdjacentHTML('afterbegin',`<div class="banner rose">Capture failed ${esc(time(S.odds_last_failure.failed_at))}: ${esc(S.odds_last_failure.error)}. Previous successful snapshots keep their original timestamps.</div>`);
  if(tab==='markets'&&S.odds_last?.events)$('#screen').insertAdjacentHTML('afterbegin',captureCoverage());
  if(tab==='system')$('#screen').insertAdjacentHTML('afterbegin',jobsPanel());
  if(window.OMEGA_PREVIEW){$('#screen').insertAdjacentHTML('afterbegin','<div class="banner amber"><span class="banner-icon">i</span><span>Interactive preview · Your real saved forecasts and one computed scenario. Launch the downloaded app to run new simulations, save bets, import data, and connect feeds.</span></div>');}
}

document.addEventListener('click',async e=>{
  if(window.OMEGA_PREVIEW && e.target.closest('a[href^="/api/"]')){e.preventDefault();notify('Exports are available in the running local app.');return;}
  const nav=e.target.closest('[data-nav]');if(nav){go(nav.dataset.nav);return;}
  const el=e.target.closest('[data-action]');if(!el||el.disabled)return;
  const a=el.dataset.action;
  try{
    if(a.startsWith('collector-')){await collectorAction(a,el);return;}
    if(a==='close')$('#modal').close();
    else if(a==='mlb-import')$('#mlb-file-input').click();
    else if(a==='mlb-backtest')go('mlbtest');
    else if(a==='delta-board')go('mlb');
    else if(a==='delta-model')go('delta');
    else if(a==='delta-backtest')go('deltatest');
    else if(a==='delta-import')$('#delta-file-input').click();
    else if(a==='delta-grade'){el.disabled=true;const r=await runJob('delta_grade');await load();notify(`${r.graded_starts} DELTA starts graded · ${r.pending} pending.`);}
    else if(a==='mlb-grade'){el.disabled=true;const r=await runJob('mlb_grade');await load();notify(`${r.graded_quotes} quotes graded. Evidence remains research only.`);}
    else if(a==='refresh'){await load();notify('Workspace refreshed.');}
    else if(a==='game'){F.game=el.dataset.game;F.page=0;render();}
    else if(a==='page'){if(el.dataset.mode==='review')F.reviewPage+=num(el.dataset.dir);else F.page+=num(el.dataset.dir);render();}
    else if(a==='player')playerModal(el.dataset.id,el.dataset.game);
    else if(a==='open-lab')go('lab');
    else if(a==='player-lab'){lab.game_id=modalPlayer.game_id;lab.team=modalPlayer.team;const others=S.forecasts.filter(r=>r.game_id===lab.game_id&&r.team===lab.team&&r.player_id!==modalPlayer.player_id).sort((a,b)=>num(b.role_point_xtc)-num(a.role_point_xtc));lab.pair=[modalPlayer.player_id,others[0].player_id];$('#modal').close();go('lab');}
    else if(a==='new-bet')newBet();
    else if(a==='settle')settleModal(el.dataset.id);
    else if(a==='quote')await quoteModal(el.dataset.id);
    else if(a==='bet-from-quote')newBet(S.quotes.find(q=>q.id===el.dataset.id));
    else if(a==='import')importModal();
    else if(a==='import-quotes')importModal('quotes');
    else if(a==='choose-file')$('#file-input').click();
    else if(a==='quote-template'){if(window.OMEGA_PREVIEW)notify('Quote templates are included in the downloaded app.');else location.href='/api/quote-template.csv';}
    else if(a==='capture-now'){el.disabled=true;el.textContent='Capturing…';const r=await runJob('capture');await load();notify(`${r.captured_events}/${r.eligible_events} games scanned · ${r.new_quotes} new quotes.`);}
    else if(a==='poly-refresh'){el.disabled=true;el.textContent='Refreshing…';await runJob('polymarket');await load();notify('Watchlist refresh finished. Inspect any connection errors.');}
    else if(a==='watch-search'){const m=polySearch.markets[num(el.dataset.index)];await api('/api/poly/watch',{token_id:m.token_id,condition_id:m.condition_id,label:m.question+' · '+m.outcome});await load();notify('Outcome added. Refresh the watchlist to capture depth.');}
    else if(a==='manual-poly')manualPoly();
    else if(a==='validate'){el.disabled=true;await runJob('validation');await load();notify('Chronological evaluation saved.');}
    else if(a==='grade'){el.disabled=true;const r=await runJob('grading');await load();notify(`${r.matched_player_games} player-games graded; missing outcomes remain ungraded.`);}
    else if(a==='historical')historicalModal();
    else if(a==='amend')amendModal(el.dataset.id);
    else if(a==='remove-poly'){await api('/api/poly/watch',{token_id:el.dataset.id,remove:true});await load();}
    else if(a==='remove-wallet'){await api('/api/poly/wallet',{address:el.dataset.address,remove:true});await load();}
    else if(a==='wallet-from-book'){await api('/api/poly/wallet',{address:el.dataset.address,label:'Observed fill participant'});await load();notify('Wallet added.');}
  }catch(err){notify(err.message,true);if(el.isConnected){el.disabled=false;if(a==='validate')el.textContent='Run evaluation';if(a==='grade')el.textContent='Grade imported finals';if(a==='capture-now')el.textContent='Capture now ↻';if(a==='poly-refresh')el.textContent='Refresh watchlist ↻';}}
});
