  if(el.dataset.filter){F[el.dataset.filter]=el.value;F.page=F.reviewPage=0;render();}
  if(el.dataset.lab){const k=el.dataset.lab;if(k==='a')lab.pair[0]=el.value;else if(k==='b')lab.pair[1]=el.value;else{lab[k]=el.value;lab.pair=[];}render();}
  if(el.id==='active-forecast'){try{await api('/api/forecasts/activate',{id:el.value});F.game='ALL';F.page=0;await load();}catch(err){notify(err.message,true);}}
  if(el.id==='bet-kind'){const parlay=el.value==='PARLAY';$('#bet-side').disabled=parlay;$('#bet-line').disabled=parlay;}
  if(el.id==='poly-auto'){try{await api('/api/poly/auto',{enabled:el.checked});await load();notify(el.checked?'Minute-by-minute watchlist refresh enabled.':'Automatic watchlist refresh paused.');}catch(err){notify(err.message,true);}}
  if(el.id==='file-input'&&el.files[0]){
    const f=el.files[0],kind=$('#import-kind')?.value||'quotes';
    try{const r=await api('/api/import',{kind,name:f.name,raw:await f.text()});$('#modal').close();await load();notify(`Imported ${r.rows} rows. Original snapshot retained.`);}catch(err){if($('#import-error'))$('#import-error').textContent=err.message;else notify(err.message,true);}finally{el.value='';}
  }
