// Long operations run on the server and survive browser navigation.
async function runJob(kind,body={}){
  const job=await api('/api/jobs',{kind,...body});
  if(S){S.jobs=S.jobs||[];S.jobs.unshift({id:job.job_id,kind,status:'RUNNING'});}
  notify('Operation started. Progress is recorded in Data & provenance.');
  for(let i=0;i<900;i++){
    await new Promise(resolve=>setTimeout(resolve,1000));
    const state=await api('/api/job?id='+encodeURIComponent(job.job_id));
    if(state.status==='COMPLETE')return state.result;
    if(state.status!=='RUNNING')throw new Error(state.result?.error||'Operation interrupted. Check Data & provenance.');
  }
  throw new Error('Still running. Check Data & provenance for completion.');
}
function captureCoverage(){const c=S.odds_last;return panel('Latest capture coverage',`${c.captured_events}/${c.eligible_events} events captured · ${c.status||'RECORDED'}${c.historical_as_of?' · Historical recovery':''}`,`<div class="panel-body"><p class="small-text">${c.missing_due_to_event_cap||0} events excluded by the sweep cap. Empty markets are recorded as empty, not as available prices.</p><div class="table-wrap"><table><thead><tr><th>Event</th><th>Status</th><th>Rows / error</th></tr></thead><tbody>${c.events.map(e=>`<tr><td class="code">${esc(e.event)}</td><td>${tag(e.status||'CAPTURED',e.status==='ERROR'?'rose':'plain')}</td><td class="wrap">${esc(e.error??e.rows??'—')}</td></tr>`).join('')}</tbody></table></div></div>`);}
function jobsPanel(){return panel('Operations & collector health','Jobs continue if you navigate away. A stopped server marks unfinished jobs interrupted.',`<div class="panel-body"><div class="status-list">${Object.entries(S.health||{}).map(([k,v])=>`<div class="status-row"><span>${esc(k)}</span><b>${esc(v.status)} · ${esc(time(v.at))}</b></div>`).join('')||'<p class="small-text subtle">Collector health appears after the first run.</p>'}</div><div class="table-wrap"><table><thead><tr><th>Operation</th><th>Status</th><th>Started</th><th>Finished</th></tr></thead><tbody>${(S.jobs||[]).map(j=>`<tr><td>${esc(j.kind)}</td><td>${tag(j.status,j.status==='FAILED'?'rose':'plain')}</td><td>${esc(time(j.created_at))}</td><td>${esc(time(j.finished_at))}</td></tr>`).join('')||'<tr><td colspan="4">No background jobs yet.</td></tr>'}</tbody></table></div></div>`);}
function validationPage(){
  const v=S.validation;
  return head('MODEL VALIDATION · CHRONOLOGICAL REPLAY','Earn the next model change.','Fit on earlier weeks, test on later weeks, and retain every result.',btn('Grade imported finals','grade')+btn('Run evaluation','validate','primary'))+
    `<div class="banner amber">Archived OMEGA remains the reference forecast. The joint simulator is a research model. Calibration replay uses previously inspected results, so it is exploratory—not an untouched holdout.</div>`+
    (v?`<div class="stats">${stat('EVALUABLE CONTROL ROWS',fmt(v.rows,0),'All participation states included',true)}${stat('FORWARD TEST FOLDS',v.folds.length,'Each test uses earlier weeks only')}${stat('ALL-ROW BIAS',signed(v.cohorts.all.bias,3),'Forecast minus actual')}${stat('MATCHED-SNAP BIAS',signed(v.cohorts.matched.bias,3),'Postgame diagnostic cohort')}</div>`+
    panel('Baseline vs calibration challenger','Fixed 100-credit prior · multiplicative mean correction · no market prices used',`<div class="table-wrap"><table><thead><tr><th>Test period</th><th>Training rows</th><th>Multiplier</th><th>Baseline MAE</th><th>Candidate MAE</th><th>Candidate bias</th><th>MAE improvement · 95% interval</th></tr></thead><tbody>${v.folds.map(f=>`<tr><td>${f.test_season} · Week ${f.test_week}</td><td>${f.training_rows} / ${f.training_games} games</td><td>${fmt(f.scale,3)}</td><td>${fmt(f.baseline.mae,3)}</td><td>${fmt(f.challenger.mae,3)}</td><td>${signed(f.challenger.bias,3)}</td><td>${signed(f.mae_improvement,3)}<small class="subtle"> [${fmt(f.mae_improvement_interval?.low,3)}, ${fmt(f.mae_improvement_interval?.high,3)}]</small></td></tr>`).join('')||'<tr><td colspan="7">At least two observed weeks are needed.</td></tr>'}</tbody></table></div><div class="panel-body"><p class="small-text">Intervals resample whole games to retain dependence among players. Lower errors on one known week do not establish future accuracy or profitability.</p>${v.folds.map(f=>`<div class="insight-callout"><strong>Matched-snap diagnostic, Week ${f.test_week}:</strong> MAE ${fmt(f.matched_snap_diagnostic.baseline.mae,3)} → ${fmt(f.matched_snap_diagnostic.challenger.mae,3)}; RMSE ${fmt(f.matched_snap_diagnostic.baseline.rmse,3)} → ${fmt(f.matched_snap_diagnostic.challenger.rmse,3)}; bias ${signed(f.matched_snap_diagnostic.baseline.bias,3)} → ${signed(f.matched_snap_diagnostic.challenger.bias,3)}. A better all-row average can worsen forecasts for observed participants. This postgame subset cannot be used to select players prospectively.</div>`).join('')}</div>`)+
    panel('Release decision',v.status,`<div class="panel-body"><h3>${esc(v.release_decision)}</h3><ul class="list-clean">${v.limits.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><p class="code">Inputs ${esc(v.input_digest)}</p></div>`,v.snapshot_id?`<a class="button small" href="/api/snapshot?id=${encodeURIComponent(v.snapshot_id)}">Download evaluation ↓</a>`:''):
    panel('Run a reproducible evaluation','Your stored results are ready.',empty('Compare a candidate with the baseline.','The audit added a fixed shrinkage calibrator trained only on earlier weeks. Run it to inspect the evidence and limits.',btn('Run evaluation','validate','primary'),'↗')))+
    `<div class="aside-card"><div class="eyebrow">GRADE NEW FINAL RESULTS</div><h3>No actual result, no grade.</h3><p>Import a Final outcome observations CSV, then choose Grade imported finals. It matches stored pregame forecasts, scores both tracks, and preserves the forecast and result sources. The supplied OUTCOME_TEMPLATE.csv describes the required target and fields. Missing players stay ungraded; sportsbook settlement remains separate.</p></div>`;
}
function historicalModal(){showModal(`<div class="modal-head"><h2>Recover historical market quotes</h2>${btn('×','close','ghost')}</div><form id="historical-form"><div class="modal-body"><div class="banner amber">Requires historical-event odds access on your The Odds API plan. This may consume more provider credits than a live call. Uses the saved games-per-sweep and daily-call limits.</div><div class="field"><label for="historical-time">As-of time (your local time)</label><input class="input" id="historical-time" name="as_of" type="datetime-local" required></div><p class="form-note">Looks for games within 48 hours of that timestamp. Quotes retain their historical snapshot time and today's retrieval time. Recovered quotes are research references and are never recorded as actual bets.</p><div class="modal-error"></div></div><div class="modal-footer"><button type="submit" class="button primary">Fetch historical snapshots</button></div></form>`);}
function amendModal(id){const b=S.bets.find(b=>b.id===id);if(!b)return;showModal(`<div class="modal-head"><h2>Correct an open ticket</h2>${btn('×','close','ghost')}</div><form id="amend-form"><div class="modal-body"><input type="hidden" name="id" value="${esc(id)}"><h3>${esc(b.selection)}</h3><div class="field-row"><div class="field"><label for="amend-stake">Correct cash stake</label><input id="amend-stake" name="stake" class="input" type="number" min=".01" step=".01" value="${b.stake_cents/100}" required></div><div class="field"><label for="amend-odds">Correct American odds</label><input id="amend-odds" name="odds" class="input" type="number" value="${b.odds}" required></div></div><div class="field"><label for="amend-source">Correction reason</label><input id="amend-source" name="source" class="input" required></div><p class="form-note">Original values and every correction remain stored. Correcting odds clears the original quote link. Reopened tickets must be settled again.</p><div class="modal-error"></div></div><div class="modal-footer"><button class="button primary" type="submit">Append correction</button></div></form>`);}

// Refresh job progress after a reload without interrupting text entry.
setInterval(async()=>{if(window.OMEGA_PREVIEW||!S?.jobs?.some(j=>j.status==='RUNNING'))return;try{const wasRunning=S.jobs.some(j=>j.status==='RUNNING');await load(false);if(!document.querySelector('#modal')?.open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){render();if(wasRunning&&!S.jobs.some(j=>j.status==='RUNNING'))notify('Background operations finished. Check Data & provenance for results.');}}catch(e){/* User can retry with Refresh; last successful state stays visible. */}},4000);

setInterval(async()=>{if(window.OMEGA_PREVIEW||!['mlb','mlbtest','delta','deltatest'].includes(tab)||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;try{await load();}catch(e){/* Last saved state remains visible. */}},30000);
